"use client";
import React, { useEffect } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/components/auth/auth-context";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  User,
  Mail,
  Shield,
  CheckCircle,
  XCircle,
  Calendar,
  ArrowLeft,
  Settings,
  Heart,
} from "lucide-react";

export default function ProfilePage() {
  const router = useRouter();
  const { user, token, logout, loading, refreshProfile } = useAuth();

  useEffect(() => {
    if (!loading && !token) {
      router.replace("/auth/login");
    }
  }, [token, loading, router]);

  useEffect(() => {
    if (token && !user) refreshProfile();
  }, [token, user, refreshProfile]);

  if (!token) return null;

  const getDisplayName = () => {
    return (
      user?.name ||
      `${(user as any)?.firstName || ""} ${(user as any)?.lastName || ""}`.trim() ||
      "User"
    );
  };

  return (
    <main className="min-h-screen bg-slate-100">
      {/* Dark Header Section */}
      <div className="bg-slate-800 pt-8 pb-20 px-4">
        <div className="max-w-2xl mx-auto">
          <Button
            onClick={() => router.push("/dashboard")}
            variant="ghost"
            size="sm"
            className="text-slate-300 hover:text-white hover:bg-slate-700 mb-6"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Dashboard
          </Button>
          
          <div className="flex items-center gap-4">
            <div>
              <h1 className="text-2xl font-bold text-white">{getDisplayName()}</h1>
              <p className="text-slate-400">{user?.email || "No email"}</p>
              <div className="flex items-center gap-2 mt-2">
                <Badge className={`${user?.isVerified ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-amber-500/20 text-amber-400 border-amber-500/30'} border`}>
                  {user?.isVerified ? (
                    <>
                      <CheckCircle className="w-3 h-3 mr-1" />
                      Verified
                    </>
                  ) : (
                    <>
                      <XCircle className="w-3 h-3 mr-1" />
                      Not Verified
                    </>
                  )}
                </Badge>
                <Badge className="bg-slate-600/50 text-slate-300 border border-slate-500/30">
                  {user?.role || "User"}
                </Badge>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Profile Content */}
      <div className="max-w-2xl mx-auto px-4 -mt-12">
        {loading && !user ? (
          <Card className="bg-white border-0 shadow-sm p-6">
            <p className="text-slate-500">Loading profile...</p>
          </Card>
        ) : user ? (
          <div className="space-y-4">
            {/* Profile Info Card */}
            <Card className="bg-white border-0 shadow-sm overflow-hidden">
              <div className="h-1 bg-gradient-to-r from-teal-500 to-cyan-500"></div>
              <CardContent className="p-0">
                <div className="divide-y divide-slate-100">
                  <div className="flex items-center gap-4 p-4">
                    <div className="w-10 h-10 bg-slate-100 rounded-lg flex items-center justify-center">
                      <User className="w-5 h-5 text-slate-600" />
                    </div>
                    <div className="flex-1">
                      <p className="text-xs text-slate-500">Full Name</p>
                      <p className="text-sm font-medium text-slate-800">{getDisplayName()}</p>
                    </div>
                  </div>
                  
                  <div className="flex items-center gap-4 p-4">
                    <div className="w-10 h-10 bg-slate-100 rounded-lg flex items-center justify-center">
                      <Mail className="w-5 h-5 text-slate-600" />
                    </div>
                    <div className="flex-1">
                      <p className="text-xs text-slate-500">Email Address</p>
                      <p className="text-sm font-medium text-slate-800">{user.email || "N/A"}</p>
                    </div>
                  </div>
                  
                  <div className="flex items-center gap-4 p-4">
                    <div className="w-10 h-10 bg-slate-100 rounded-lg flex items-center justify-center">
                      <Shield className="w-5 h-5 text-slate-600" />
                    </div>
                    <div className="flex-1">
                      <p className="text-xs text-slate-500">Account Role</p>
                      <p className="text-sm font-medium text-slate-800 capitalize">{user.role || "User"}</p>
                    </div>
                  </div>
                  
                  <div className="flex items-center gap-4 p-4">
                    <div className="w-10 h-10 bg-slate-100 rounded-lg flex items-center justify-center">
                      <Calendar className="w-5 h-5 text-slate-600" />
                    </div>
                    <div className="flex-1">
                      <p className="text-xs text-slate-500">Member Since</p>
                      <p className="text-sm font-medium text-slate-800">
                        {user.createdAt
                          ? new Date(user.createdAt).toLocaleDateString("en-US", {
                              year: "numeric",
                              month: "long",
                              day: "numeric",
                            })
                          : "N/A"}
                      </p>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Quick Links Card */}
            <Card className="bg-white border-0 shadow-sm overflow-hidden">
              <div className="h-1 bg-gradient-to-r from-orange-500 to-amber-500"></div>
              <CardContent className="p-4">
                <p className="text-sm font-medium text-slate-800 mb-3">Quick Links</p>
                <div className="grid grid-cols-2 gap-2">
                  <Button
                    onClick={() => router.push("/meal-planner/profile")}
                    variant="outline"
                    size="sm"
                    className="justify-start border-slate-200 text-slate-700 hover:bg-slate-800 hover:text-white hover:border-slate-800"
                  >
                    <Heart className="w-4 h-4 mr-2 text-rose-500" />
                    Health Profile
                  </Button>
                  <Button
                    onClick={() => router.push("/support")}
                    variant="outline"
                    size="sm"
                    className="justify-start border-slate-200 text-slate-700 hover:bg-slate-800 hover:text-white hover:border-slate-800"
                  >
                    <Settings className="w-4 h-4 mr-2 text-slate-500" />
                    Support
                  </Button>
                </div>
              </CardContent>
            </Card>


          </div>
        ) : (
          <Card className="bg-white border-0 shadow-sm p-6">
            <p className="text-slate-500">Unable to load profile.</p>
          </Card>
        )}
      </div>
    </main>
  );
}
